// SPDX-License-Identifier: MIT

/**
 * @title IETSAccessControls
 * @author Ethereum Tag Service <team@ets.xyz>
 *
 *  ███████╗████████╗███████╗
 *  ██╔════╝╚══██╔══╝██╔════╝
 *  █████╗     ██║   ███████╗
 *  ██╔══╝     ██║   ╚════██║
 *  ███████╗   ██║   ███████║`
 *  ╚══════╝   ╚═╝   ╚══════╝
 *
 * @notice This is the interface for the ETSAccessControls contract which allows ETS Core Dev
 * Team to administer roles and control access to various parts of the ETS Platform.
 * ETSAccessControls contract contains a mix of public and administrator only functions.
 */

pragma solidity ^0.8.10;

import { IAccessControlUpgradeable } from "@openzeppelin/contracts-upgradeable/access/IAccessControlUpgradeable.sol";

interface IETSAccessControls is IAccessControlUpgradeable {
    // Custom errors
    error ChannelNameExists(string name);
    error ChannelNameTooShort(uint256 length);
    error ChannelNameTooLong(uint256 length);
    error CallerIsNotChannel(address caller);
    error NotChannelOwner(address caller, address expectedOwner);
    error NewOwnerAlreadyOwnsChannel(address newOwner);
    error SenderOwnsChannel(address sender);

    /**
     * @dev emitted when the ETS Platform address is set.
     *
     * @param newAddress wallet address platform is being set to.
     * @param prevAddress previous platform address.
     */
    event PlatformSet(address newAddress, address prevAddress);

    /**
     * @dev emitted when a Channel contract is added & enabled in ETS.
     *
     * Channel contracts are not required implement all ETS Core API functions. Therefore, to ease
     * testing of ETS Core API fuinctions, ETS permits addition of ETS owned wallet addresses as Channels.
     *
     * @param channel Channel contract address.
     */
    event ChannelAdded(address channel);

    /**
     * @dev emitted when a Channel contract is paused or unpaused.
     *
     * @param channel Address that had pause toggled.
     */
    event ChannelLockToggled(address channel);

    /**
     * @notice Sets the Platform wallet address. Can only be called by address with DEFAULT_ADMIN_ROLE.
     *
     * @param _platform The new Platform address to set.
     */
    function setPlatform(address payable _platform) external;

    /**
     * @notice Adds a Channel contract to ETS. Can only be called by address
     * with DEFAULT_ADMIN_ROLE.
     *
     * @param _channel Address of the Channel contract. Must conform to IETSChannel.
     * @param _name Human readable name of the Channel.
     * @param _owner Address of channel owner.
     */
    function registerChannel(address _channel, string calldata _name, address _owner) external;

    /**
     * @notice Pause channel given the channel owner address. Callable by Platform only.
     *
     * @param _channelOwner Address of the Channel owner.
     */
    function pauseChannelByOwnerAddress(address _channelOwner) external;

    /**
     * @notice Change the channel owner as stored in ETSAccessControls. Callable from Channel only.
     * Called via changeOwner() on a channel.
     *
     * @param _currentOwner Address of the current channel owner.
     * @param _newOwner Address of the new channel owner.
     */
    function changeChannelOwner(address _currentOwner, address _newOwner) external;

    /**
     * @notice Pauses/Unpauses a Channel contract. Can only be called by address
     * with DEFAULT_ADMIN_ROLE.
     *
     * @param _channel Address of the Channel contract.
     */
    function toggleChannelLock(address _channel) external;

    /**
     * @notice Sets the role admin for a given role. An address with role admin can grant or
     * revoke that role for other addresses. Can only be called by address with DEFAULT_ADMIN_ROLE.
     *
     * @param _role bytes32 representation of role being administered.
     * @param _adminRole bytes32 representation of administering role.
     */
    function setRoleAdmin(bytes32 _role, bytes32 _adminRole) external;

    /**
     * @notice Checks whether given address has SMART_CONTRACT role.
     *
     * @param _addr Address being checked.
     * @return boolean True if address has SMART_CONTRACT role.
     */
    function isSmartContract(address _addr) external view returns (bool);

    /**
     * @notice Checks whether given address has DEFAULT_ADMIN_ROLE role.
     *
     * @param _addr Address being checked.
     * @return boolean True if address has DEFAULT_ADMIN_ROLE role.
     */
    function isAdmin(address _addr) external view returns (bool);

    /**
     * @notice Checks whether given address has EVENT_PROCESSOR_ROLE role.
     *
     * @param _addr Address being checked.
     * @return boolean True if address has EVENT_PROCESSOR_ROLE role.
     */
    function isEventProcessor(address _addr) external view returns (bool);

    /**
     * @notice Checks whether given address can act as channel factory.
     *
     * @param _addr Address being checked.
     * @return boolean True if address can act as channel factory.
     */
    function isChannelFactory(address _addr) external view returns (bool);

    /**
     * @notice Checks whether given address is a channel.
     *
     * @param _addr Address being checked.
     * @return boolean True if address can be a channel.
     */
    function isChannel(address _addr) external view returns (bool);

    /**
     * @notice Checks whether given address is a registered Channel and not paused.
     *
     * @param _addr Address being checked.
     * @return boolean True if address is a Channel and not paused.
     */
    function isChannelAndNotPaused(address _addr) external view returns (bool);

    /**
     * @notice Checks channel is paused by ETS Platform.
     *
     * @param _addr Address being checked.
     * @return boolean True if channel address is paused by platform.
     */
    function isChannelLocked(address _addr) external view returns (bool);

    /**
     * @notice Checks whether given address owns a channel.
     *
     * @param _addr Address being checked.
     * @return boolean True if address owns a channel.
     */
    function isChannelByOwner(address _addr) external view returns (bool);

    /**
     * @notice Checks whether given address has RELAYER_ADMIN role.
     *
     * @param _addr Address being checked.
     * @return boolean True if address has RELAYER_ADMIN role.
     */
    function isChannelAdmin(address _addr) external view returns (bool);

    /**
     * @notice Checks whether given Channel Name is a registered Channel.
     *
     * @param _name Name being checked.
     * @return boolean True if _name is a Channel.
     */
    function isChannelByName(string calldata _name) external view returns (bool);

    /**
     * @notice Checks whether given address is a registered Channel.
     *
     * @param _addr Address being checked.
     * @return boolean True if address is a registered Channel.
     */
    function isChannelByAddress(address _addr) external view returns (bool);

    /**
     * @notice Get channel address from it's name.
     *
     * @param _name Name of channel.
     * @return Address of channel.
     */
    function getChannelAddressFromName(string calldata _name) external view returns (address);

    /**
     * @notice Get channel name from it's address.
     *
     * @param _address Adsdress of channel.
     * @return Name of channel.
     */
    function getChannelNameFromAddress(address _address) external view returns (string calldata);

    /**
     * @notice Get channel address from its owner address.
     *
     * @param _address address of channel owner.
     * @return Address of channel.
     */
    function getChannelAddressFromOwner(address _address) external view returns (address);

    /**
     * @notice Returns wallet address for ETS Platform.
     *
     * @return ETS Platform address.
     */
    function getPlatformAddress() external view returns (address payable);
}

project/contracts/interfaces/IETSEnrichT.content:
// SPDX-License-Identifier: MIT

/**
 * @title IETSEnrichTarget
 * @author Ethereum Tag Service <team@ets.xyz>
 *
 *  ███████╗████████╗███████╗
 *  ██╔════╝╚══██╔══╝██╔════╝
 *  █████╗     ██║   ███████╗
 *  ██╔══╝     ██║   ╚════██║
 *  ███████╗   ██║   ███████║`
 *  ╚══════╝   ╚═╝   ╚══════╝
 *
 * @notice This is the interface for the ETSEnrichTarget.sol contract that serves as an API gateway
 * for requesting target enrichment via the ETS Event Processor.
 *
 * In order to keep the on-chain recording of new Target records lightweight and inexpensive,
 * the createTarget() function (ETSTarget.sol) requires only a URI string (targetURI). To augment this,
 * we have developed a hybrid onchain/off-chain Target enrichment flow for collecting additional 
 * metadata about a Target and saving it back on-chain.
 *
 * The flow begins with the requestEnrichTarget() function which takes a targetId as an argument. 
 * If the Target exists, the function emits an EnrichTargetRequested event. The ETS Event Processor 
 * listens for these events and triggers the enrichment flow, which extracts metadata from the Target URI,
 * uploads it to Arweave, and updates the Target record on-chain.
 */

pragma solidity ^0.8.10;

/// @title IETSEnrichTarget
/// @notice Interface for the ETSEnrichTarget API gateway contract
interface IETSEnrichTarget {
    // Events
    event EnrichTargetRequested(uint256 indexed targetId, address indexed requestor);
    event TargetEnriched(
        uint256 indexed targetId,
        string title,
        string description,
        string imageUrl,
        string keywords
    );
    /// @notice Request to enrich a target's metadata
    /// @param _targetId The target ID to enrich
    /// @dev Emits EnrichTargetRequested event for the Event Processor to handle
    function requestEnrichTarget(uint256 _targetId) external;

    /// @notice Emit enrichment data for a target (called by Event Processor)
    /// @param _targetId The target ID being enriched
    /// @param _title The extracted title metadata
    /// @param _description The extracted description metadata
    /// @param _imageUrl The extracted image URL metadata
    /// @param _keywords Comma-separated keywords metadata
    /// @dev Only callable by EVENT_PROCESSOR_ROLE
    /// @dev Emits TargetEnriched event for The Graph to index
    function enrichTarget(
        uint256 _targetId,
        string memory _title,
        string memory _description,
        string memory _imageUrl,
        string memory _keywords
    ) external;
}

project/contracts/interfaces/IETSToken.s.content:
// SPDX-License-Identifier: MIT

/**
 * @title IETSToken
 * @author Ethereum Tag Service <team@ets.xyz>
 *
 *  ███████╗████████╗███████╗
 *  ██╔════╝╚══██╔══╝██╔════╝
 *  █████╗     ██║   ███████╗
 *  ██╔══╝     ██║   ╚════██║
 *  ███████╗   ██║   ███████║`
 *  ╚══════╝   ╚═╝   ╚══════╝
 *
 * @notice This is the interface for the ETSToken.sol core contract that governs the creation & management
 * of Ethereum Tag Service tags with Zora ERC-20 coin integration.
 *
 * TAGs are represented by deterministic Zora ERC-20 coin addresses that store tag metadata including
 * three-tier identifier system, origin attribution data with "Channel" and "Creator" addresses.
 *
 * TAGs use a three-tier identifier system: originalInput ("#BiTCOin"), displayVersion ("#Bitcoin"),
 * and machineName ("bitcoin"). Only one TAG exists per normalized machine name regardless of case.
 *
 * TAG coin addresses are deterministically computed using Zora's coinAddress() function, enabling
 * predictable addressing and seamless integration with Zora's trading infrastructure.
 *
 * TAGs may only be generated by Channel contracts via ETS core (ETS.sol)
 */

pragma solidity ^0.8.10;

interface IETSToken {
    // Custom errors
    error CallerIsNotETSCore(address caller);
    error AccessDenied(address caller);
    error CallerIsNotChannel(address caller);
    error AddressCannotBeZero();
    error CallerNotAdminInNewContract(address caller);
    error TagAlreadyExists(address coinAddress);
    error ZoraFactoryNotConfigured();
    error InvalidTagFormat(uint256 length, uint256 minLength, uint256 maxLength);
    error TagMustStartWithHash();
    error SpacesInTag();
    error TagContainsPrefix();

    /**
     * @notice Data structure for TAG Token with three-tier identifier system.
     *
     * @param originalInput Exact user input string (e.g., "#BiTCOin").
     * @param displayVersion Canonical display format (e.g., "#Bitcoin").
     * @param machineName Normalized identifier for uniqueness (e.g., "bitcoin").
     * @param coinAddress Deterministic Zora ERC-20 coin address.
     * @param creator Address interacting with channel to initiate TAG creation.
     * @param channel Address of channel that facilitated TAG creation.
     * @param timestamp Block timestamp when TAG was created.
     */
    struct Tag {
        string originalInput;
        string displayVersion;
        string machineName;
        address coinAddress;
        address creator;
        address channel;
        uint256 timestamp;
    }

    // Events

    /**
     * @dev emitted when the maximum character length of TAG display string is set.
     *
     * @param maxStringLength maximum character length of string.
     */
    event TagMaxStringLengthSet(uint256 maxStringLength);

    /**
     * @dev emitted when the minimum character length of TAG display string is set.
     *
     * @param minStringLength minimum character length of string.
     */
    event TagMinStringLengthSet(uint256 minStringLength);

    /**
     * @dev emitted when the ETS core contract is set.
     *
     * @param ets ets core contract address.
     */
    event ETSCoreSet(address ets);

    /**
     * @dev emitted when the ETS Access Controls is set.
     *
     * @param etsAccessControls contract address access controls is set to.
     */
    event AccessControlsSet(address etsAccessControls);

    /**
     * @dev emitted when a new TAG is created with Zora coin integration.
     *
     * @param coinAddress Deterministic Zora ERC-20 coin address (primary identifier).
     * @param originalInput Exact user input string (e.g., "#BiTCOin").
     * @param displayVersion Canonical display format (e.g., "#Bitcoin").
     * @param machineName Normalized identifier (e.g., "bitcoin").
     * @param creator Address credited with creating the TAG.
     * @param channel Address of channel that facilitated creation.
     * @param timestamp Block timestamp when TAG was created.
     */
    event TagCreated(
        address indexed coinAddress,
        string originalInput,
        string displayVersion,
        string machineName,
        address indexed creator,
        address indexed channel,
        uint256 timestamp
    );


    /**
     * @dev emitted when the Zora factory contract address is set.
     *
     * @param factoryAddress Zora factory contract address.
     */
    event ZoraFactoryAddressSet(address factoryAddress);

    /**
     * @dev emitted when the Zora creator EOA address is set.
     *
     * @param eoaAddress EOA address for creating Zora coins.
     */
    event ZoraCreatorEOASet(address eoaAddress);

    /**
     * @dev emitted when the Zora platform referrer address is set.
     *
     * @param referrerAddress Platform referrer address.
     */
    event ZoraPlatformReferrerSet(address referrerAddress);

    /**
     * @dev emitted when the Zora pool configuration is set.
     *
     * @param poolConfig Encoded pool configuration bytes.
     */
    event ZoraPoolConfigSet(bytes poolConfig);

    // ============ OWNER INTERFACE ============

    /**
     * @notice Admin function to set maximum character length of TAG display string.
     *
     * @param _tagMaxStringLength maximum character length of string.
     */
    function setTagMaxStringLength(uint256 _tagMaxStringLength) external;

    /**
     * @notice Admin function to set minimum character length of TAG display string.
     *
     * @param _tagMinStringLength minimum character length of string.
     */
    function setTagMinStringLength(uint256 _tagMinStringLength) external;

    // ============ PUBLIC INTERFACE ============

    /**
     * @notice Get TAG coin address from tag string.
     *
     * Combo function that accepts a tag string and returns its coin address if it exists,
     * or creates a new TAG and returns corresponding coin address.
     *
     * Only ETS Core can call this function.
     *
     * @param _tag Tag string.
     * @param _channel Address of Channel contract calling ETS Core.
     * @param _creator Address credited with creating TAG.
     * @return coinAddress Zora ERC-20 coin address.
     */
    function getOrCreateTagId(
        string calldata _tag,
        address payable _channel,
        address payable _creator
    ) external payable returns (address coinAddress);

    /**
     * @notice Create TAG with Zora coin integration from tag string.
     *
     * Reverts if tag exists or is invalid.
     *
     * Only ETS Core can call this function.
     *
     * @param _tag Tag string.
     * @param _channel Address of channel that facilitated TAG creation.
     * @param _creator Address credited with creating TAG.
     * @return coinAddress Deterministic Zora ERC-20 coin address.
     */
    function createTag(
        string calldata _tag,
        address payable _channel,
        address payable _creator
    ) external payable returns (address coinAddress);


    // ============ PUBLIC VIEW FUNCTIONS ============

    /**
     * @notice Function to deterministically compute & return a TAG coin address.
     *
     * Every TAG and its associated data struct is mapped by its deterministic Zora coin address.
     * This address is computed using Zora's coinAddress() function with normalized machine name.
     *
     * Note: Function does not verify if TAG record exists.
     *
     * @param _tag Tag string.
     * @return coinAddress Deterministic Zora ERC-20 coin address.
     */
    function computeCoinAddress(string memory _tag) external view returns (address);

    /**
     * @notice Check that a TAG exists for a given tag string.
     *
     * @param _tag Tag string.
     * @return true if TAG exists; false if not.
     */
    function tagExistsByString(string calldata _tag) external view returns (bool);

    /**
     * @notice Check that TAG exists for a given coin address.
     *
     * @param _coinAddress Zora ERC-20 coin address.
     * @return true if TAG exists; false if not.
     */
    function tagExistsByAddress(address _coinAddress) external view returns (bool);

    /**
     * @notice Retrieve a TAG record for a given tag string.
     *
     * Note: returns a struct with empty members when no TAG exists.
     *
     * @param _tag Tag string.
     * @return TAG record as Tag struct.
     */
    function getTagByString(string calldata _tag) external view returns (Tag memory);

    /**
     * @notice Retrieve a TAG record for a given coin address.
     *
     * Note: returns a struct with empty members when no TAG exists.
     *
     * @param _coinAddress Zora ERC-20 coin address.
     * @return TAG record as Tag struct.
     */
    function getTagByAddress(address _coinAddress) external view returns (Tag memory);

    /**
     * @notice Retrieve wallet address for ETS Platform.
     *
     * @return wallet address for ETS Platform.
     */
    function getPlatformAddress() external view returns (address payable);
}

